const IMG=/^https?:\/\/\S+\.(png|jpe?g|webp|gif|svg)(\?\S*)?$|^\/img\/\w+$/i;
const LN=s=>(s||'').split('\n').map(x=>x.trim()).filter(Boolean);
const NT=s=>LN(s).filter(x=>!IMG.test(x)).join('\n');
const img=b=>LN(b).find(x=>IMG.test(x))||'',pic=r=>img(r.vi_b)||img(r.en_b);
const txt=(b,n=155)=>LN(b).filter(x=>!IMG.test(x)).map(x=>x.replace(/^(## |- )/,'')).join(' ').slice(0,n);
const B=s=>{let o='',u=0;for(const x of LN(s)){const li=x.startsWith('- ');if(u&&!li){o+='</ul>';u=0}if(li){if(!u){o+='<ul>';u=1}o+=`<li>${E(x.slice(2))}</li>`}else o+=IMG.test(x)?`<img src="${E(x)}" alt="">`:x.startsWith('## ')?`<h3>${E(x.slice(3))}</h3>`:`<p>${E(x)}</p>`}return o+(u?'</ul>':'')};
const SL=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const U=(l,p)=>l=='en'?'/en'+(p=='/'?'':p):p;
const sha=async s=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s)))].map(b=>b.toString(16).padStart(2,'0')).join('');
const LX={vi:'Vietnamese',en:'English'};
const LOOP=t=>/(\b[\p{L}\d]+\b)(\s+\1\b){3,}/iu.test(t);
function good(a,b){if(!b||LOOP(b))return false;const C=(t,r)=>t.split('\n').filter(x=>r.test(x.trim())).length;
 if(C(a,/^## /)!=C(b,/^## /)||C(a,/^- /)!=C(b,/^- /))return false;
 for(const x of LN(a))if(IMG.test(x)&&!b.includes(x))return false;
 const r=b.length/(a.length||1);return r>.35&&r<3}
async function llm(env,s,f,t){const r=await env.AI.run('@cf/meta/llama-3.3-70b-instruct-fp8-fast',{messages:[{role:'system',content:`You are a professional technical translator for industrial sealing equipment. Translate the user text from ${LX[f]} to ${LX[t]}. Keep every line break and blank line. Keep the line prefixes "## " and "- " exactly. Leave lines that are only an image path such as /img/abc unchanged. Keep brand names, model names, numbers and units. Output only the translation, no notes.`},{role:'user',content:s}],max_tokens:4096,temperature:.2});return String(r.response||'').replace(/^(here is|here's|sure|translation)[^\n]*\n+/i,'').trim()}
async function tr(env,s,f,t){s=(s||'').replace(/\r/g,'');if(!LN(s).some(x=>!IMG.test(x)))return s;
 try{const o=await llm(env,s,f,t);if(good(s,o))return o}catch(e){}
 let n=0;return(await Promise.all(s.split('\n').map(async x=>{const m=x.match(/^(## |- )?([\s\S]*)$/);if(!m[2].trim()||IMG.test(m[2].trim())||++n>38)return x;try{const o=(await env.AI.run('@cf/meta/m2m100-1.2b',{text:m[2],source_lang:L[f],target_lang:L[t]})).translated_text;return LOOP(o)||o.length>m[2].length*3+30?x:(m[1]||'')+o}catch(e){return x}}))).join('\n')}
